<span class="line"><span class="__shiki_1t8gfj">ssh-keygen</span><span class="__shiki_dzsirb"> -t</span><span class="__shiki_mdbnqw"> rsa</span><span class="__shiki_dzsirb"> -C</span><span class="__shiki_mdbnqw"> &quot;root&quot;</span></span>
